  if (!req.id) throw invalid("id is required");
  return { id: String(req.id) };
}

function toProto(row: any) {
  return {
    id: row.id ?? "",
    title: row.title ?? "",
    body: row.body ?? "",
    published: row.published ?? false,
    createdAt: toTs(row.createdAt),
    updatedAt: toTs(row.updatedAt),
  };
}

function createData(req: any): any {
  const data = {
    title: req.title || null,
    body: req.body || null,
    published: Boolean(req.published),
  };
  required(data, ["title", "body"]);
  return data;
}

// UpdatePost replaces every field (the proto has no field mask).
function updateData(req: any): any {
  const data = {
    title: req.title || null,
    body: req.body || null,
    published: Boolean(req.published),
  };
  required(data, ["title", "body"]);
  return data;
}

export const postService = {
  async listPost(call: Call, cb: Callback) {
    try {
      const { page, pageSize, skip } = pageOf(call.request);
