        prisma.post.findMany({ skip, take: pageSize, orderBy: { id: "asc" } }),
        prisma.post.count(),
      ]);
      cb(null, { items: rows.map(toProto), total, page, pageSize });
    } catch (err) {
      fail(cb, err);
    }
  },
