      cb(null, toProto(row));
    } catch (err) {
      fail(cb, err);
    }
  },
  async createPost(call: Call, cb: Callback) {
    try {
      cb(null, toProto(await prisma.post.create({ data: createData(call.request) })));
    } catch (err) {
      fail(cb, err);
    }
  },
  async updatePost(call: Call, cb: Callback) {
    try {
